use crate::PyError;
use crate::bytecode::{BinaryOperator, ComparisonOperator};
use pyre_object::{PyObjectRef, w_bool_from};

use crate::{
    CompareOp, add, and_, compare, floordiv, getitem, invert, is_true, lshift, mod_, mul, neg, or_,
    pow, rshift, sub, truediv, xor,
};

/// Maps an in-place `BinaryOperator` to its special-method name
/// (`__iadd__` etc.), or `None` for non-in-place operators.
///
/// `InplacePower` is absent: `inplace_pow` is hand-written rather than
/// generated by `_make_inplace_impl` and looks `__ipow__` up itself, so a row
/// here would call the slot a second time.
fn inplace_dunder_name(op: BinaryOperator) -> Option<&'static str> {
    Some(match op {
        BinaryOperator::InplaceAdd => "__iadd__",
        BinaryOperator::InplaceSubtract => "__isub__",
        BinaryOperator::InplaceMultiply => "__imul__",
        BinaryOperator::InplaceFloorDivide => "__ifloordiv__",
        BinaryOperator::InplaceRemainder => "__imod__",
        BinaryOperator::InplaceTrueDivide => "__itruediv__",
        BinaryOperator::InplaceLshift => "__ilshift__",
        BinaryOperator::InplaceMatrixMultiply => "__imatmul__",
        BinaryOperator::InplaceRshift => "__irshift__",
        BinaryOperator::InplaceAnd => "__iand__",
        BinaryOperator::InplaceOr => "__ior__",
        BinaryOperator::InplaceXor => "__ixor__",
        _ => return None,
    })
}

/// `sq_inplace_repeat` is not a numeric slot, so a builtin sequence times an
/// operand with no `__index__` never reaches `__imul__`: the in-place multiply
/// falls through to `sequence_repeat`, which reports the multiplier rather
/// than running the slot's own converter.
///
/// A sequence *subclass* that defines its own `__imul__` is exempt — that
/// override is a real numeric slot and runs whatever the multiplier is, so
/// `x = LI([1]); x *= "s"` is `LI.__imul__`, not the multiplier TypeError.
fn skips_inplace_special(a: PyObjectRef, b: PyObjectRef, op: BinaryOperator) -> bool {
    matches!(op, BinaryOperator::InplaceMultiply)
        && unsafe { crate::objspace::descroperation::is_repeat_sequence(a) }
        && !unsafe {
            crate::objspace::descroperation::seq_repeat_override(
                a,
                crate::objspace::descroperation::RepeatDunder::IMul,
            )
        }
        && unsafe { crate::baseobjspace::lookup(b, "__index__").is_none() }
}

pub fn binary_value(
    mut a: PyObjectRef,
    mut b: PyObjectRef,
    op: BinaryOperator,
) -> Result<PyObjectRef, PyError> {
    // descroperation.py `inplace_impl` — consult the in-place
    // special first; fall through to the binary op below when absent or
    // `NotImplemented`.
    // Written as a let-chain rather than `Option::filter`: the combinator's
    // closure captures `a`, `b` and `op`, so it reaches the JIT as an
    // aggregate plus a `call_once` whose path the host does not bind, and a
    // walk of this handler stops at that residual.  The chain evaluates the
    // guard only in the `Some` arm, exactly as `filter` did.
    if let Some(idunder) = inplace_dunder_name(op)
        && !skips_inplace_special(a, b, op)
    {
        // `seq_bug_compat` applies only to `+=` / `*=`; pass the reflected
        // name so the builtin-sequence rhs-first branch can fire.
        let (rdunder, seq_bug_compat) = match op {
            BinaryOperator::InplaceAdd => (Some("__radd__"), true),
            BinaryOperator::InplaceMultiply => (Some("__rmul__"), true),
            _ => (None, false),
        };
        if let Some(result) = pyre_object::with_roots!(a, b => crate::objspace::descroperation::try_inplace_special(
            a,
            b,
            idunder,
            rdunder,
            seq_bug_compat,
        ))? {
            return Ok(result);
        }
    }
    // `_make_binop_impl` and `_make_inplace_impl` generate two
    // families from one dispatch; the only thing that separates them is the
    // symbol their fallback TypeError names, so each arm shares a body and
    // passes its own spelling — `&` for `a & b`, `&=` for `a &= b`.
    let symbol = operator_symbol(op);
    use crate::objspace::descroperation as desc;
    match op {
        BinaryOperator::Add | BinaryOperator::InplaceAdd => desc::add_impl(a, b, symbol),
        BinaryOperator::Subtract | BinaryOperator::InplaceSubtract => desc::sub_impl(a, b, symbol),
        BinaryOperator::Multiply | BinaryOperator::InplaceMultiply => desc::mul_impl(a, b, symbol),
        BinaryOperator::FloorDivide | BinaryOperator::InplaceFloorDivide => {
            desc::floordiv_impl(a, b, symbol)
        }
        BinaryOperator::Remainder | BinaryOperator::InplaceRemainder => {
            desc::mod_impl(a, b, symbol)
        }
        BinaryOperator::TrueDivide | BinaryOperator::InplaceTrueDivide => {
            desc::truediv_impl(a, b, symbol)
        }
        BinaryOperator::Power => pow(a, b),
        // PyPy `pyopcode.py:INPLACE_POWER` calls `space.inplace_pow`
        // directly; unlike the generated `inplace_impl` family this operation
        // has its own three-argument-aware dispatch in descroperation.py,
        // and with it its own `**=` fallback.
        BinaryOperator::InplacePower => desc::inplace_pow(a, b),
        BinaryOperator::Lshift | BinaryOperator::InplaceLshift => desc::lshift_impl(a, b, symbol),
        BinaryOperator::MatrixMultiply | BinaryOperator::InplaceMatrixMultiply => {
            desc::matmul_impl(a, b, symbol)
        }
        BinaryOperator::Rshift | BinaryOperator::InplaceRshift => desc::rshift_impl(a, b, symbol),
        BinaryOperator::And | BinaryOperator::InplaceAnd => desc::and_impl(a, b, symbol),
        // mappingproxy `__ior__` (read-only) raises TypeError, handled
        // above by `try_inplace_special`; both fall through to `or_`.
        BinaryOperator::Or | BinaryOperator::InplaceOr => desc::or_impl(a, b, symbol),
        BinaryOperator::Xor | BinaryOperator::InplaceXor => desc::xor_impl(a, b, symbol),
        BinaryOperator::Subscr => getitem(a, b),
    }
}

/// The symbol descroperation.py bakes into an operation's fallback
/// TypeError: the operator for a binary op, the augmented assignment for an
/// in-place one, read from `ObjSpace.MethodTable`'s symbol column.
///
/// `Power`, `InplacePower` and `Subscr` are listed for the match to be
/// exhaustive; each raises through a dispatch that spells its own message,
/// and each keeps the spelling the table gives it.
fn operator_symbol(op: BinaryOperator) -> &'static str {
    match op {
        BinaryOperator::Add => "+",
        BinaryOperator::Subtract => "-",
        BinaryOperator::Multiply => "*",
        BinaryOperator::FloorDivide => "//",
        BinaryOperator::Remainder => "%",
        BinaryOperator::TrueDivide => "/",
        BinaryOperator::Power => "**",
        BinaryOperator::Lshift => "<<",
        BinaryOperator::MatrixMultiply => "@",
        BinaryOperator::Rshift => ">>",
        BinaryOperator::And => "&",
        BinaryOperator::Or => "|",
        BinaryOperator::Xor => "^",
        BinaryOperator::InplaceAdd => "+=",
        BinaryOperator::InplaceSubtract => "-=",
        BinaryOperator::InplaceMultiply => "*=",
        BinaryOperator::InplaceFloorDivide => "//=",
        BinaryOperator::InplaceRemainder => "%=",
        BinaryOperator::InplaceTrueDivide => "/=",
        BinaryOperator::InplacePower => "**=",
        BinaryOperator::InplaceLshift => "<<=",
        BinaryOperator::InplaceMatrixMultiply => "@=",
        BinaryOperator::InplaceRshift => ">>=",
        BinaryOperator::InplaceAnd => "&=",
        BinaryOperator::InplaceOr => "|=",
        BinaryOperator::InplaceXor => "^=",
        BinaryOperator::Subscr => "getitem",
    }
}

fn null_operand_error(what: &str) -> PyError {
    PyError::type_error(format!("{what} on null operand"))
}

/// Body of [`binary_value_from_tag`].  The public function stays
/// `inline(never)` so the codewriter mints a graph; the residual C ABI
/// wrapper calls this directly so compiled traces do not pay that hop.
#[inline]
fn binary_value_from_tag_inner(
    a: PyObjectRef,
    b: PyObjectRef,
    op_tag: i64,
) -> Result<PyObjectRef, PyError> {
    // A compiled force that has not written a local yet hands a NULL
    // here.  It must raise, or the inlined path returns a NULL result
    // without an exception (`ValueError: call failed`).
    if a.is_null() || b.is_null() {
        return Err(null_operand_error("binary operation"));
    }
    // In-place tags (13-24) must consult the in-place special (`__iadd__`
    // etc.) first; route them through `binary_value`.  Tags 0-12 use the
    // plain dispatch below.
    if op_tag > 12 {
        let Some(op) = crate::runtime_ops::binary_op_from_tag(op_tag) else {
            return Err(PyError::type_error(format!(
                "unsupported binary op tag: {op_tag}"
            )));
        };
        return binary_value(a, b, op);
    }
    match op_tag {
        0 => add(a, b),
        1 => sub(a, b),
        2 => mul(a, b),
        3 => floordiv(a, b),
        4 => mod_(a, b),
        5 => truediv(a, b),
        6 => getitem(a, b),
        7 => pow(a, b),
        8 => lshift(a, b),
        9 => rshift(a, b),
        10 => and_(a, b),
        11 => or_(a, b),
        12 => xor(a, b),
        _ => Err(PyError::type_error(format!(
            "unsupported binary op tag: {op_tag}"
        ))),
    }
}

/// `inline(never)` is load-bearing: rustc otherwise folds this body into its
/// one-call wrapper and the codewriter never mints the graph a trace descends
/// (`specialize.rs try_walker_orthodox_binary_op`).
#[inline(never)]
pub fn binary_value_from_tag(
    a: PyObjectRef,
    b: PyObjectRef,
    op_tag: i64,
) -> Result<PyObjectRef, PyError> {
    binary_value_from_tag_inner(a, b, op_tag)
}

pub fn compare_value(
    a: PyObjectRef,
    b: PyObjectRef,
    op: ComparisonOperator,
) -> Result<PyObjectRef, PyError> {
    // Same helper flatten's COMPARE_OP descends, so a jitted `COMPARE_OP`
    // and a 2-arg HLOp share one minted graph (`compare_value_from_tag`).
    compare_value_from_tag(a, b, crate::runtime_ops::compare_op_tag(op))
}

/// Body of [`compare_value_from_tag`].  See [`binary_value_from_tag_inner`].
#[inline]
fn compare_value_from_tag_inner(
    a: PyObjectRef,
    b: PyObjectRef,
    op_tag: i64,
) -> Result<PyObjectRef, PyError> {
    // A compiled force that has not written a local yet hands a NULL
    // here.  It must raise, or the inlined path returns a NULL result
    // without an exception (`ValueError: call failed`).
    if a.is_null() || b.is_null() {
        return Err(null_operand_error("comparison"));
    }
    // Do not pin here: this body is the graph `CompareOpDescent` walks
    // (`compare_value_from_tag`). A `dont_look_inside` pin at the head
    // blocks that descent and is what doubled guard_failures / dropped
    // `compare_op_descent`. The MayForce C ABI copies are published in
    // `jit_compare_value_from_tag` only.
    // CONTAINS_OP routes through the compare-residual machinery.
    // `a` is the needle, `b` the container (flatten lowers the args
    // as `[item, container]`).
    if crate::runtime_ops::compare_op_tag_is_contains(op_tag) {
        let found = crate::baseobjspace::contains(b, a)?;
        let result = if op_tag == crate::runtime_ops::COMPARE_OP_NOT_CONTAINS {
            !found
        } else {
            found
        };
        return Ok(w_bool_from(result));
    }
    // CHECK_EXC_MATCH (tag 10): `except T:` is `exception_match(type(exc), T)`.
    // The codewriter residualises that as `compare_fn(exc, T, 10)`, and
    // `cpu.compare_fn` is this helper (`jit_compare_value_from_tag`).
    // Without this arm the residual TypeErrors ("unsupported compare op
    // tag: 10"), Truth sees NULL, and the handler takes the mismatch
    // re-raise — a caught `ValueError` escapes the frame.
    if op_tag == crate::runtime_ops::ISINSTANCE_OP_TAG {
        crate::eval::validate_check_exc_match_class(b)?;
        return Ok(w_bool_from(crate::eval::check_exc_match_against(a, b)));
    }
    // IS_OP: `space.is_w`, not raw pointer identity.  Infallible.
    if crate::runtime_ops::compare_op_tag_is_identity(op_tag) {
        let same = crate::baseobjspace::is_w(a, b);
        let result = if op_tag == crate::runtime_ops::COMPARE_OP_IS_NOT {
            !same
        } else {
            same
        };
        return Ok(w_bool_from(result));
    }
    let op = match op_tag {
        0 => CompareOp::Lt,
        1 => CompareOp::Le,
        2 => CompareOp::Gt,
        3 => CompareOp::Ge,
        4 => CompareOp::Eq,
        5 => CompareOp::Ne,
        _ => {
            return Err(PyError::type_error(format!(
                "unsupported compare op tag: {op_tag}"
            )));
        }
    };
    // Two exact builtin ints: `compare_slot` only. `is_int_like` is
    // true for an int subclass (`is_int` is the vtable/`ob_type`
    // check); taking the slot on that shape skips `LiarInt.__lt__`
    // and returns the raw payload (`True` where the override returns
    // `"LT"`). `compare` is loop-free (`try_compare_override` is
    // residual) so other callers (`operator`, containers) can look
    // inside it the way `comparison_impl` is looked inside.
    let both_exact_int = unsafe {
        crate::objspace::descroperation::is_int_like(a)
            && crate::objspace::descroperation::is_int_like(b)
            && crate::objspace::descroperation::both_exact_builtin_instances_promoted(a, b)
    };
    if both_exact_int {
        return crate::objspace::descroperation::compare_slot(a, b, op);
    }
    compare(a, b, op)
}

/// `inline(never)` for the same reason as [`binary_value_from_tag`]: the
/// codewriter must mint the graph a trace descends.
#[inline(never)]
pub fn compare_value_from_tag(
    a: PyObjectRef,
    b: PyObjectRef,
    op_tag: i64,
) -> Result<PyObjectRef, PyError> {
    compare_value_from_tag_inner(a, b, op_tag)
}

pub fn unary_negative_value(value: PyObjectRef) -> Result<PyObjectRef, PyError> {
    neg(value)
}

pub fn unary_invert_value(value: PyObjectRef) -> Result<PyObjectRef, PyError> {
    invert(value)
}

pub fn unary_positive_value(value: PyObjectRef) -> Result<PyObjectRef, PyError> {
    crate::baseobjspace::pos(value)
}

pub fn unary_not_value(value: PyObjectRef) -> Result<PyObjectRef, PyError> {
    crate::baseobjspace::not_(value)
}

/// CALL_INTRINSIC_1 ListToTuple — convert a list to a tuple (star
/// unpacking).  Shared by the interpreter's `list_to_tuple` and the JIT
/// residual `bh_list_to_tuple_fn`.  Allocates a fresh tuple.
///
/// pyopcode.py does `space.call_function(space.w_tuple, w_l)` (accepts any
/// iterable); the compiler only ever emits INTRINSIC_LIST_TO_TUPLE right
/// after a `BUILD_LIST` + `LIST_EXTEND` chain, so the operand is always an
/// exact list.  A non-iterable `*arg` is already rejected upstream by
/// LIST_EXTEND ("Value after * must be an iterable"), so the non-list
/// TypeError below is an unreachable defensive guard.
pub fn list_to_tuple_value(value: PyObjectRef) -> Result<PyObjectRef, PyError> {
    unsafe {
        if pyre_object::is_list(value) {
            let items = pyre_object::w_list_items_copy_as_vec_mode(
                value,
                majit_metainterp::jit::we_are_jitted(),
            );
            let _roots = pyre_object::gc_roots::push_roots();
            let base = pyre_object::gc_roots::pin_roots(&items);
            let live: Vec<PyObjectRef> = (0..items.len())
                .map(|i| pyre_object::gc_roots::shadow_stack_get(base + i))
                .collect();
            return Ok(pyre_object::w_tuple_new(live));
        }
    }
    Err(PyError::type_error("expected list for list_to_tuple"))
}

// ── Pattern matching (PEP 634) ──
//
// The four value-level entry points below are shared by the interpreter's
// stack-based opcode handlers (`eval.rs`) and the JIT residuals
// (`bh_match_*_fn`), so a traced `match` statement and an interpreted one
// run exactly the same code.

/// `MATCH_MAPPING` — push whether the subject is a mapping.
/// `pyopcode.py` reads `flag_patma_collection` and, when the type carries
/// neither marker, falls back to `ismapping_w`.  [3.15-spec] That fallback is
/// dropped: `ceval` tests `Py_TPFLAGS_MAPPING` alone, so a class with
/// `keys` and `__getitem__` that was never registered is not a mapping
/// (`pypy3` matches it).  The built-ins and `_abc` registration stamp the
/// marker, so the flag read is the whole test.
pub fn match_mapping_value(subject: PyObjectRef) -> PyObjectRef {
    let is_mapping = unsafe {
        let ty = crate::typedef::r#type(subject).map_or(std::ptr::null_mut(), |p| p.as_ptr());
        pyre_object::typeobject::w_type_get_flag_patma_collection(ty) == b'M'
    };
    w_bool_from(is_mapping)
}

/// `MATCH_SEQUENCE` — push whether the subject is a sequence.
/// `pyopcode.py`, with the same [3.15-spec] drop of the `issequence_w`
/// fallback as [`match_mapping_value`] (a class with only `__getitem__` is not
/// a sequence; `pypy3` matches it), and `pyopcode.py`'s str / bytes /
/// bytearray exclusion kept.
pub fn match_sequence_value(subject: PyObjectRef) -> PyObjectRef {
    let is_sequence = unsafe {
        let ty = crate::typedef::r#type(subject).map_or(std::ptr::null_mut(), |p| p.as_ptr());
        match pyre_object::typeobject::w_type_get_flag_patma_collection(ty) {
            b'M' => false,
            flag => {
                let is_sequence = flag == b'S';
                is_sequence
                    && !crate::baseobjspace::isinstance_str_w(subject)
                    && !crate::baseobjspace::isinstance_bytes_like_w(subject)
            }
        }
    };
    w_bool_from(is_sequence)
}

/// `MATCH_KEYS` — look every key of the pattern up in the subject and
/// return a tuple of the values, or `None` when any key is absent.
/// MATCH_MAPPING already proved the subject is a mapping, so the keys are
/// looked up directly without re-gating (`Python/ceval.c match_keys`).
/// `pyopcode.py MATCH_KEYS` is `@jit.unroll_safe`.
#[majit_macros::unroll_safe]
pub fn match_keys_value(subject: PyObjectRef, keys: PyObjectRef) -> Result<PyObjectRef, PyError> {
    let key_items = unsafe { pyre_object::tupleobject::w_tuple_items_copy_as_vec(keys) };
    // Every round runs `subject.get`, which is application-level Python: it
    // can relocate the subject and each value already looked up, and it can
    // reach a collection while the fresh set and sentinel still have no heap
    // edge.  Hold all of them on the shadow stack and read each back at its
    // use; the results accumulate in slots rather than in a native `Vec`,
    // which would keep pre-move addresses.  The keys go the same way: being
    // hashable does not make one immobile, and a value pattern that names a
    // tuple (`case {Cls.KEY: v}`) puts a nursery-allocated key in `key_items`.
    let _roots = pyre_object::gc_roots::push_roots();
    let mut live = Vec::with_capacity(1 + key_items.len());
    live.push(subject);
    live.extend_from_slice(&key_items);
    let subject_slot = pyre_object::gc_roots::pin_roots(&live);
    let keys_base = subject_slot + 1;
    // pyopcode.py:1797-1818 — a key repeated in the pattern is rejected
    // before it binds anything; track keys already looked up and raise on
    // a duplicate. Each key is looked up with `map.get(key, sentinel)`
    // rather than subscription so a mapping subclass that defines
    // `__missing__` (defaultdict) neither creates entries nor raises; a
    // sentinel result means the key is absent.  The sentinel is a fresh
    // `object()` (match_keys `dummy = object()`), so a value present in the
    // subject can never be mistaken for the absent marker.
    let seen_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_set_new());
    let sentinel_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(pyre_object::w_instance_new(
        crate::typedef::gettypeobject(&pyre_object::pyobject::INSTANCE_TYPE),
    ));
    let values_base = pyre_object::gc_roots::shadow_stack_len();
    let mut value_count = 0usize;
    let mut all_match = true;
    for key_index in 0..key_items.len() {
        let key = pyre_object::gc_roots::shadow_stack_get(keys_base + key_index);
        let w_seen = pyre_object::gc_roots::shadow_stack_get(seen_slot);
        if crate::baseobjspace::contains(w_seen, key)? {
            let key = pyre_object::gc_roots::shadow_stack_get(keys_base + key_index);
            let key_repr = unsafe { crate::display::py_repr_wtf8(key)? };
            return Err(PyError::value_error(crate::display::wtf8_format!(
                "mapping pattern checks duplicate key (",
                key_repr,
                ")"
            )));
        }
        unsafe {
            pyre_object::w_set_add(
                pyre_object::gc_roots::shadow_stack_get(seen_slot),
                pyre_object::gc_roots::shadow_stack_get(keys_base + key_index),
            )
        };
        let w_sentinel = pyre_object::gc_roots::shadow_stack_get(sentinel_slot);
        let w_value = crate::baseobjspace::call_method(
            pyre_object::gc_roots::shadow_stack_get(subject_slot),
            "get",
            &[
                pyre_object::gc_roots::shadow_stack_get(keys_base + key_index),
                w_sentinel,
            ],
        );
        if w_value.is_null() {
            return Err(crate::call::take_call_error()
                .unwrap_or_else(|| PyError::type_error("mapping pattern lookup failed")));
        }
        // `is_w` can collect. This slot is also the accumulation entry when
        // the value is not the sentinel, so the result tuple stays contiguous.
        let value_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_value);
        if crate::baseobjspace::is_w(
            pyre_object::gc_roots::shadow_stack_get(value_slot),
            pyre_object::gc_roots::shadow_stack_get(sentinel_slot),
        ) {
            all_match = false;
            break;
        }
        value_count += 1;
    }
    Ok(if all_match {
        let values: Vec<PyObjectRef> = (0..value_count)
            .map(|i| pyre_object::gc_roots::shadow_stack_get(values_base + i))
            .collect();
        pyre_object::w_tuple_new(values)
    } else {
        pyre_object::w_none()
    })
}

/// `MATCH_CLASS count` — return the extracted-attribute tuple when the
/// subject matches the class pattern, else `None`.  `count` is the number
/// of positional sub-patterns; `kwd_attrs` is the keyword attribute-name
/// tuple.
/// `pyopcode.py _match_class` is `@jit.unroll_safe`.
#[majit_macros::unroll_safe]
pub fn match_class_value(
    subject: PyObjectRef,
    cls: PyObjectRef,
    kwd_attrs: PyObjectRef,
    count: usize,
) -> Result<PyObjectRef, PyError> {
    if unsafe { !pyre_object::typeobject::is_type(cls) } {
        return Err(PyError::type_error("called match pattern must be a class"));
    }
    let type_name = unsafe { pyre_object::w_type_get_name(cls) };

    // `isinstance`, the `__match_args__` probe and each attribute fetch below
    // run Python, so the subject moves under the pattern and so does every
    // attribute extracted before it.  Pin the subject and read it back at each
    // use; hold the extracted values as shadow-stack slots rather than as raw
    // copies and read them back when the result tuple is built.  `cls` is
    // pinned with them: a pattern class can be a young type object.  Pinning
    // `kwd_attrs` is what makes the collector walk it, so its name slots are
    // forwarded too.
    let roots = pyre_object::gc_roots::push_roots();
    let pair = pyre_object::gc_roots::pin_roots(&[subject, kwd_attrs, cls]);
    let subject_slot = pair;
    let kwd_attrs_slot = pair + 1;
    let cls_slot = pair + 2;
    let subject = || roots.get(subject_slot);
    let kwd_attrs = || roots.get(kwd_attrs_slot);
    let cls = || roots.get(cls_slot);

    if !crate::baseobjspace::isinstance(subject(), cls())? {
        return Ok(pyre_object::w_none());
    }

    let mut extracted: Vec<usize> = Vec::new();
    let mut seen: Vec<String> = Vec::new();

    if count > 0 {
        let match_args = match crate::baseobjspace::getattr_str(cls(), "__match_args__") {
            Ok(v) => Some(v),
            Err(e) if e.kind == crate::PyErrorKind::AttributeError => None,
            Err(e) => return Err(e),
        };
        if let Some(match_args) = match_args {
            if unsafe { !pyre_object::is_tuple(match_args) } {
                let got = unsafe {
                    pyre_object::w_type_get_name(
                        crate::typedef::r#type(match_args)
                            .map_or(std::ptr::null_mut(), |p| p.as_ptr()),
                    )
                };
                return Err(PyError::type_error(format!(
                    "{type_name}.__match_args__ must be a tuple (got {got})"
                )));
            }
            let ma = unsafe { pyre_object::tupleobject::w_tuple_items_copy_as_vec(match_args) };
            if ma.len() < count {
                let plural = if ma.len() == 1 { "" } else { "s" };
                return Err(PyError::type_error(format!(
                    "{type_name}() accepts {} positional sub-pattern{plural} ({count} given)",
                    ma.len()
                )));
            }
            for attr_obj in ma.into_iter().take(count) {
                // pyopcode.py:2105-2108 — reject a non-string element before it
                // reaches the attribute lookup.  The bundled test only asserts
                // the exception type, so the quoted `%T` wording is kept.
                if unsafe { !crate::baseobjspace::isinstance_str_w(attr_obj) } {
                    let got = crate::type_methods::arg_type_name(attr_obj);
                    return Err(PyError::type_error(format!(
                        "__match_args__ elements must be strings (got '{got}')"
                    )));
                }
                let attr_name = match unsafe { pyre_object::w_str_get_value_opt(attr_obj) } {
                    Some(s) => s,
                    None => {
                        let got = unsafe {
                            pyre_object::w_type_get_name(
                                crate::typedef::r#type(attr_obj)
                                    .map_or(std::ptr::null_mut(), |p| p.as_ptr()),
                            )
                        };
                        return Err(PyError::type_error(format!(
                            "__match_args__ elements must be strings (got {got})"
                        )));
                    }
                };
                if seen.iter().any(|s| s == attr_name) {
                    return Err(PyError::type_error(format!(
                        "{type_name}() got multiple sub-patterns for attribute '{attr_name}'"
                    )));
                }
                seen.push(attr_name.to_string());
                match crate::baseobjspace::getattr_str(subject(), attr_name) {
                    Ok(v) => {
                        extracted.push(pyre_object::gc_roots::shadow_stack_len());
                        let _ = roots.pin_root(v);
                    }
                    Err(e) if e.kind == crate::PyErrorKind::AttributeError => {
                        return Ok(pyre_object::w_none());
                    }
                    Err(e) => return Err(e),
                }
            }
        } else {
            // No `__match_args__`: the builtin "atomic" types (int, str,
            // bytes, ...) match the subject itself as their single
            // positional sub-pattern (Py_TPFLAGS_MATCH_SELF).
            let is_self = unsafe { pyre_object::typeobject::w_type_has_match_self(cls()) };
            if is_self {
                if count == 1 {
                    extracted.push(subject_slot);
                } else {
                    return Err(PyError::type_error(format!(
                        "{type_name}() accepts 1 positional sub-pattern ({count} given)"
                    )));
                }
            } else {
                return Err(PyError::type_error(format!(
                    "{type_name}() accepts 0 positional sub-patterns ({count} given)"
                )));
            }
        }
    }

    let kwd_items = unsafe { pyre_object::tupleobject::w_tuple_items_copy_as_vec(kwd_attrs()) };
    for name_obj in kwd_items {
        let name = match unsafe { pyre_object::w_str_get_value_opt(name_obj) } {
            Some(s) => s,
            None => return Err(PyError::type_error("Attribute name must be string")),
        };
        if seen.iter().any(|s| s == name) {
            return Err(PyError::type_error(format!(
                "{type_name}() got multiple sub-patterns for attribute '{name}'"
            )));
        }
        seen.push(name.to_string());
        match crate::baseobjspace::getattr_str(subject(), name) {
            Ok(v) => {
                extracted.push(pyre_object::gc_roots::shadow_stack_len());
                let _ = roots.pin_root(v);
            }
            Err(e) if e.kind == crate::PyErrorKind::AttributeError => {
                return Ok(pyre_object::w_none());
            }
            Err(e) => return Err(e),
        }
    }

    let values: Vec<PyObjectRef> = extracted.iter().map(|&slot| roots.get(slot)).collect();
    Ok(pyre_object::w_tuple_new(values))
}

pub fn truth_value(value: PyObjectRef) -> Result<bool, PyError> {
    is_true(value)
}

pub fn bool_value_from_truth(value: bool) -> PyObjectRef {
    w_bool_from(value)
}

/// Whether [`load_common_constant_value`] returns one prebuilt object for
/// `cc` (a singleton, the interned `""` or `-1`, a builtin class), which the
/// JIT pushes as a constant the way `flowcontext.py LOAD_CONST` does. `all`
/// and `any` build a fresh builtin function on every call.
pub fn common_constant_is_prebuilt(cc: crate::bytecode::CommonConstant) -> bool {
    use crate::bytecode::CommonConstant;
    !matches!(cc, CommonConstant::BuiltinAll | CommonConstant::BuiltinAny)
}

/// LOAD_COMMON_CONSTANT — resolve a `CommonConstant` to the object the
/// interpreter pushes.  Shared by the interpreter's `load_common_constant`
/// handler and the JIT residual `bh_load_common_constant_fn` so both
/// resolve identical objects (immortal type/exception classes for the
/// class variants; a freshly built builtin function for `all`/`any`).
pub fn load_common_constant_value(cc: crate::bytecode::CommonConstant) -> PyObjectRef {
    use crate::bytecode::CommonConstant;
    match cc {
        CommonConstant::AssertionError => crate::builtins::lookup_exc_class("AssertionError")
            .unwrap_or_else(|| {
                crate::typedef::gettypeobject(
                    &pyre_object::interp_exceptions::EXC_ASSERTION_ERROR_TYPE,
                )
            }),
        CommonConstant::NotImplementedError => {
            crate::builtins::lookup_exc_class("NotImplementedError").unwrap_or_else(|| {
                crate::make_builtin_function("NotImplementedError", |_args| {
                    Err(crate::PyError::type_error("not implemented"))
                })
            })
        }
        CommonConstant::BuiltinTuple => {
            crate::typedef::gettypeobject(&pyre_object::pyobject::TUPLE_TYPE)
        }
        CommonConstant::BuiltinAll => crate::make_module_builtin_function_with_arity(
            "all",
            crate::builtins::builtin_all_fn,
            1,
        ),
        CommonConstant::BuiltinAny => crate::make_module_builtin_function_with_arity(
            "any",
            crate::builtins::builtin_any_fn,
            1,
        ),
        CommonConstant::BuiltinList => {
            crate::typedef::gettypeobject(&pyre_object::pyobject::LIST_TYPE)
        }
        CommonConstant::BuiltinSet => {
            crate::typedef::gettypeobject(&pyre_object::setobject::SET_TYPE)
        }
        CommonConstant::None => pyre_object::w_none(),
        CommonConstant::EmptyStr => {
            pyre_object::unicodeobject::box_str_constant(rustpython_wtf8::Wtf8::new(""))
        }
        CommonConstant::True => w_bool_from(true),
        CommonConstant::False => w_bool_from(false),
        CommonConstant::MinusOne => pyre_object::w_small_int_const(-1),
    }
}

/// pyopcode.py `BUILD_LIST_FROM_ARG`: `space.newlist([], sizehint=length_hint)`.
///
/// Shared by the interpreter opcode (`opcode_build_list_from_arg`) and the
/// JIT residual.  `length_hint` exceptions that are not async are swallowed
/// and the hint falls back to 0; an async exception propagates.
///
/// `#[inline(never)]` keeps one body for both callers.
#[inline(never)]
pub fn newlist_from_iter_hint(last_val: PyObjectRef) -> Result<PyObjectRef, PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let iter_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(last_val);
    let hint = match crate::length_hint(pyre_object::gc_roots::shadow_stack_get(iter_slot), 0) {
        Ok(h) => h,
        Err(mut e) => {
            if e.r#async(pyre_object::PY_NULL) {
                return Err(e);
            }
            0
        }
    };
    Ok(pyre_object::listobject::w_list_new_with_sizehint(hint))
}

/// LIST_EXTEND — extend `list` in place with the items of `iterable`.
/// Shared by the interpreter's `list_extend` handler and the JIT residual
/// `bh_list_extend_fn`.  Mirrors `list.extend`: fast paths for list/tuple
/// sources, generic iterator-protocol fallback otherwise (which surfaces
/// "Value after * must be an iterable, not <T>" when not iterable).
pub fn list_extend_value(list: PyObjectRef, mut iterable: PyObjectRef) -> Result<(), PyError> {
    // pyopcode.py LIST_EXTEND calls the target list's `extend` method.  The
    // builtin body preserves exact-list/tuple storage fast paths while list
    // and tuple subclasses go through `iter()` so an overridden `__iter__`
    // is observed.
    match pyre_object::with_roots!(iterable => crate::type_methods::list_method_extend(&[list, iterable]))
    {
        Ok(_) => Ok(()),
        Err(error) if crate::baseobjspace::is_iterable(iterable) => Err(error),
        Err(_) => {
            let type_name = crate::baseobjspace::object_functionstr_type_name(iterable);
            Err(PyError::type_error(format!(
                "Value after * must be an iterable, not {type_name}"
            )))
        }
    }
}

/// SET_ADD — `set.add(value)` (or `list.append` for the list-shaped
/// accumulator).  Shared by the interpreter's `set_add` and the JIT
/// residual `bh_set_add_fn`.  `set` is peeked, mutated in place.
///
/// pyopcode.py uses `space.call_method(w_set, 'add', ...)`; this stores
/// directly by container type instead.  These accumulators only ever touch
/// the container the surrounding BUILD_SET / BUILD_MAP / BUILD_LIST just
/// pushed — a set/dict/list comprehension or display has no syntax to
/// target a user subclass — so the container is always the exact builtin
/// type and the method-dispatch vs direct-store distinction is not
/// observable (SET_UPDATE / DICT_UPDATE below take the same shortcut; the
/// *source* iterable/mapping, which can be arbitrary, still goes through
/// the iterator / mapping protocol).
pub fn set_add_value(set: PyObjectRef, value: PyObjectRef) -> Result<(), PyError> {
    unsafe {
        if pyre_object::is_set_or_frozenset(set) {
            // `IntegerSetStrategy.add` with `is_correct_type(w_key)`:
            // `d[self.unwrap(w_key)] = None`. A plain int is stored unwrapped
            // and needs no `try_hash_value` first. The helper reads the
            // strategy under the set's stripe lock and answers -1 for any
            // other.
            if pyre_object::listobject::is_plain_int1(value)
                && pyre_object::setobject::jit_int_set_add(
                    set,
                    pyre_object::listobject::plain_int_w(value),
                ) >= 0
            {
                return Ok(());
            }
            // `try_hash_value` may run a user `__hash__` that allocates and
            // triggers a moving minor collection; `set`/`value` must be
            // shadow-stack roots across it, then reloaded, or the store
            // below can write through a relocated (stale) pointer.  Its
            // digest keys the store, so the element is hashed once.  The
            // slots are read back as `base + <literal>` through the scope,
            // and the error arm is a `match`, not a closure, so the
            // codewriter erases the bracket and the JIT inlines the body.
            let roots = pyre_object::gc_roots::push_roots();
            let base = roots.base();
            let _ = roots.pin_root(set);
            let _ = roots.pin_root(value);
            let hash = match crate::builtins::try_hash_value(roots.get(base + 1)) {
                Ok(hash) => hash,
                Err(err) => {
                    return Err(crate::baseobjspace::wrap_set_element_hash_error(
                        roots.get(base + 1),
                        err,
                    ));
                }
            };
            pyre_object::w_set_add_hashed_checked(roots.get(base), roots.get(base + 1), hash)
                .map_err(crate::baseobjspace::map_set_update_error)?;
        } else if pyre_object::is_list(set) {
            pyre_object::w_list_append(set, value);
        }
    }
    Ok(())
}

/// SET_UPDATE — `set.update(iterable)` (or `list.extend` for the
/// list-shaped accumulator).  Shared by the interpreter's `set_update`
/// and the JIT residual `bh_set_update_fn`.  `set` is peeked, mutated in
/// place; a user iterator or element `__hash__` may run Python.
pub fn set_update_value(set: PyObjectRef, iterable: PyObjectRef) -> Result<(), PyError> {
    unsafe {
        if pyre_object::is_set_or_frozenset(set) {
            // `collect_iterable` runs Python (`__iter__` / `__next__`) and
            // pops its own roots before returning, so both `set` and the
            // source have to sit on this frame's stack *before* that call.
            // Pinning `set` only after the drain published the pre-move
            // address (`gc_mapping_unpack_roots_its_source`).
            let _roots = pyre_object::gc_roots::push_roots();
            let sp = _roots.pin_roots(&[set, iterable]);
            let items =
                crate::builtins::collect_iterable(pyre_object::gc_roots::shadow_stack_get(sp + 1))?;
            let item_base = pyre_object::gc_roots::pin_roots(&items);
            let item_len = items.len();
            // `_update_from_iterable`: `w_set.add(w_item)` per item.
            for i in 0..item_len {
                set_add_value(
                    pyre_object::gc_roots::shadow_stack_get(sp),
                    pyre_object::gc_roots::shadow_stack_get(item_base + i),
                )?;
            }
        } else if pyre_object::is_list(set) {
            let items = if pyre_object::is_list(iterable) {
                pyre_object::w_list_items_copy_as_vec_mode(
                    iterable,
                    majit_metainterp::jit::we_are_jitted(),
                )
            } else if pyre_object::is_tuple(iterable) {
                pyre_object::w_tuple_items_copy_as_vec(iterable)
            } else {
                return Ok(());
            };
            // `w_list_append` can grow the items block through a nursery
            // malloc that collects, so the list and the copied items are
            // read back from the shadow stack on every append.
            let _roots = pyre_object::gc_roots::push_roots();
            let sp = _roots.pin_roots(&[set]);
            let item_base = pyre_object::gc_roots::pin_roots(&items);
            for i in 0..items.len() {
                pyre_object::w_list_append(
                    pyre_object::gc_roots::shadow_stack_get(sp),
                    pyre_object::gc_roots::shadow_stack_get(item_base + i),
                );
            }
        }
    }
    Ok(())
}

/// MAP_ADD — `dict[key] = value`.  Shared by the interpreter's `map_add`
/// and the JIT residual `bh_map_add_fn`.  `dict` is peeked, mutated in
/// place; the key is hashed before the raw dict store, so a user `__hash__`
/// may run Python.
pub fn map_add_value(
    dict: PyObjectRef,
    key: PyObjectRef,
    value: PyObjectRef,
) -> Result<(), PyError> {
    unsafe {
        // Root across `try_hash_value` (a possible collection point from a
        // user `__hash__`) and reload before the store, mirroring
        // `set_add_value`.
        let _roots = pyre_object::gc_roots::push_roots();
        let sp = _roots.pin_roots(&[dict, key, value]);
        let key = _roots.get(sp + 1);
        let hash = crate::builtins::try_hash_value(key)
            .map_err(|err| crate::baseobjspace::wrap_dict_key_hash_error(key, err))?;
        let dict = pyre_object::gc_roots::shadow_stack_get(sp);
        let key = pyre_object::gc_roots::shadow_stack_get(sp + 1);
        let value = pyre_object::gc_roots::shadow_stack_get(sp + 2);
        pyre_object::w_dict_store_hashed_checked(dict, key, value, hash)
            .map_err(|_| crate::baseobjspace::take_pending_dict_key_error(key))?;
    }
    Ok(())
}

/// `PyDict_Update` — `dict_merge` with `override`, which takes the generic
/// branch for a non-dict operand and calls `PyMapping_Keys` on it.  A `source`
/// with no `keys()` percolates its own `AttributeError` from there, and that
/// is the error `framelocalsproxy_or` and `_PyNamespace_New` report; the
/// `DICT_UPDATE` wrapper below is what rewrites it.
pub fn dict_update(dict: PyObjectRef, source: PyObjectRef) -> Result<(), PyError> {
    // pyopcode.py `DICT_UPDATE` → `space.call_method(w_dict, "update", w_item)`
    // → `descr_update` → `update1`.  `update1` copies a dict subclass whose
    // `__iter__` is still `dict.__iter__` from the backing mapping (issue 2435)
    // and otherwise walks `keys()` / `space.getitem`.
    if unsafe { crate::baseobjspace::isinstance_dict_w(source) } {
        return crate::type_methods::dict_update1(dict, source);
    }
    // The scope opens ahead of the key fetch, not after it: `getattr_str`, the
    // `keys()` call and the iteration of whatever it answers are all Python,
    // and `dict` is a `W_DictObject`, which relocates.  Pinning the pair below
    // the fetch published the words that were live before it.
    let _roots = pyre_object::gc_roots::push_roots();
    let sp = _roots.pin_roots(&[dict, source]);
    let source_now = || pyre_object::gc_roots::shadow_stack_get(sp + 1);
    let keys_method = crate::baseobjspace::getattr_str(source_now(), "keys")?;
    let keys_obj = crate::call::call_function_impl_result(keys_method, &[])?;
    let keys = crate::type_methods::mapping_keys_listview(source_now(), keys_obj)?;
    unsafe {
        // A generic mapping's keys are not pre-validated the way a dict's
        // are (`update1` above copies from the backing mapping) —
        // `d[key] = mapping[key]` still hashes `key`, so an unhashable one
        // must raise here too.  `dict`, `source`, and every collected key
        // are rooted for the loop's duration: `getitem` (arbitrary
        // `__getitem__`) and `try_hash_value` (arbitrary `__hash__`) both
        // may allocate and move them.
        let key_base = pyre_object::gc_roots::pin_roots(&keys);
        let key_len = keys.len();
        for i in 0..key_len {
            let key = pyre_object::gc_roots::shadow_stack_get(key_base + i);
            let val = crate::baseobjspace::getitem(source_now(), key)?;
            let _val_root = pyre_object::gc_roots::push_roots();
            let val_slot = pyre_object::gc_roots::shadow_stack_len();
            let _ = pyre_object::gc_roots::pin_root(val);
            let key = pyre_object::gc_roots::shadow_stack_get(key_base + i);
            let hash = crate::builtins::try_hash_value(key)
                .map_err(|err| crate::baseobjspace::wrap_dict_key_hash_error(key, err))?;
            let dict = pyre_object::gc_roots::shadow_stack_get(sp);
            let key = pyre_object::gc_roots::shadow_stack_get(key_base + i);
            let val = pyre_object::gc_roots::shadow_stack_get(val_slot);
            pyre_object::w_dict_store_hashed_checked(dict, key, val, hash)
                .map_err(|_| crate::baseobjspace::take_pending_dict_key_error(key))?;
        }
    }
    Ok(())
}

/// DICT_UPDATE — `PyDict_Update`, then `_DICT_UPDATE`'s rewrite: an
/// `AttributeError` the update surfaced is reported as `'<T>' object is not a
/// mapping` only when the operand has no `keys` (`PyObject_HasAttrWithError`).
/// When `keys` is present the original `AttributeError` propagates; when the
/// lookup itself raises a non-`AttributeError`, that error propagates.
/// Shared by the interpreter's `dict_update` and the JIT residual
/// `bh_dict_update_fn`.
pub fn dict_update_value(dict: PyObjectRef, source: PyObjectRef) -> Result<(), PyError> {
    let roots = pyre_object::gc_roots::push_roots();
    let base = roots.pin_roots(&[dict, source]);
    match dict_update(roots.get(base), roots.get(base + 1)) {
        Err(e) if e.kind == crate::PyErrorKind::AttributeError => {
            // `_DICT_UPDATE`: after the merge fails with an AttributeError,
            // look up `keys` on the operand (`PyObject_HasAttrWithError`).
            // Absent → "'%T' object is not a mapping"; present → original
            // AttributeError; a non-AttributeError from the lookup propagates.
            let mut e = e;
            let e_slot = e.pin(&roots);
            match crate::baseobjspace::getattr_str_impl(roots.get(base + 1), "keys", true, true) {
                Ok(value) if value.is_null() => {}
                Err(e2) if e2.kind == crate::PyErrorKind::AttributeError => {}
                Ok(_) => {
                    e.reload(&roots, e_slot);
                    return Err(e);
                }
                Err(e2) => return Err(e2),
            }
            let type_name = crate::error::type_name_of(roots.get(base + 1));
            Err(PyError::type_error(format!(
                "'{type_name}' object is not a mapping"
            )))
        }
        other => other,
    }
}

/// DICT_MERGE — merge `source` into `dict` with duplicate-key checks.
/// Shared by the interpreter's `dict_merge` and the JIT residual
/// `bh_dict_merge_fn`.  `w_callable` is the peeked callable used only for
/// error-message prefixes; a `keys()`/`__getitem__` may run Python.
pub fn dict_merge_value(
    dict: PyObjectRef,
    source: PyObjectRef,
    w_callable: PyObjectRef,
) -> Result<(), PyError> {
    // pyopcode.py `_dict_merge`.
    // `__len__`, `keys()`, `__getitem__` and `__contains__` all run Python, so
    // every step below is a collection point, and the three operands arrive as
    // native copies no root walker updates — the dispatch peeked them and the
    // frame slots that rooted them are gone by the time a subclass' `keys()`
    // returns.  Publish them and read each one back per use: a stale target
    // reaches `dict.__contains__` as a receiver its own type check rejects,
    // and a stale source is read as a mapping it no longer is.  `dict_update`
    // above brackets the same walk.
    let _roots = pyre_object::gc_roots::push_roots();
    let root_base = _roots.pin_roots(&[dict, source, w_callable]);
    let dict = || pyre_object::gc_roots::shadow_stack_get(root_base);
    let source = || pyre_object::gc_roots::shadow_stack_get(root_base + 1);
    let w_callable = || pyre_object::gc_roots::shadow_stack_get(root_base + 2);
    let w_dict_type = crate::typedef::gettypeobject(&pyre_object::pyobject::DICT_TYPE);
    let dict_type_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_dict_type);
    let w_dict_type = || pyre_object::gc_roots::shadow_stack_get(dict_type_slot);
    // `space.isinstance_w(w_dict, space.w_dict)` accepts dict subclasses;
    // a non-dict target is a RuntimeError, not a TypeError.
    if !unsafe { crate::baseobjspace::isinstance_w(dict(), w_dict_type()) } {
        let type_name = unsafe { (*(*dict()).ob_type).name };
        return Err(PyError::new(
            crate::PyErrorKind::RuntimeError,
            format!("expected a dict, got {type_name}"),
        ));
    }
    // `space.len_w` is a generic `__len__` dispatch — a raw `w_dict_len`
    // would be UB on a dict subclass whose layout is not `W_DictObject`.
    let l1 = crate::baseobjspace::len_w(dict())?;
    // pyopcode.py `_dict_merge`: `unroll_safe = jit.isvirtual(w_dict) and l1 < 10`.
    let mut unroll_safe = majit_rlib::jit::isvirtual(&dict()) && l1 < 10;
    let source_is_dict = unsafe { crate::baseobjspace::isinstance_w(source(), w_dict_type()) };
    if !source_is_dict {
        unroll_safe = false;
        // [3.15-spec] pyopcode.py _dict_merge rejects a non-mapping up front with ismapping_w; _DICT_MERGE has no
        // pre-check and _PyEval_FormatKwargsError rewrites only an AttributeError from an operand without `keys`
        // (an object with keys() but no __getitem__ fails in __getitem__ instead), so the check is left to the
        // `keys` lookup in _dict_merge_loop.
    } else {
        // `pyopcode.py _dict_merge`: an empty target calls `update1`
        // (`dictmultiobject.py`), which copies a dict subclass whose
        // `__iter__` is still `dict.__iter__` from the backing mapping
        // (issue 2435) and otherwise walks `keys()` / `space.getitem`.
        // An empty source is a no-op.
        let l2 = crate::baseobjspace::len_w(source())?;
        if l1 == 0 {
            crate::type_methods::dict_update1(dict(), source())?;
            return Ok(());
        }
        if l2 == 0 {
            return Ok(());
        }
        unroll_safe = unroll_safe && majit_rlib::jit::isvirtual(&source()) && l2 < 10;
    }
    if source_is_dict && crate::type_methods::dict_subclass_uses_default_iter(source()) {
        return _dict_merge_dict(dict(), source(), w_callable());
    }
    _dict_merge_loop(dict(), source(), unroll_safe, w_callable())
}

/// pyopcode.py `_dict_merge_loop`.
/// `@jit.look_inside_iff(lambda space, w_dict, w_item, unroll_safe, w_function: unroll_safe)`.
fn _dict_merge_loop_iff(
    _w_dict: PyObjectRef,
    _w_item: PyObjectRef,
    unroll_safe: bool,
    _w_function: PyObjectRef,
) -> bool {
    unroll_safe
}

#[majit_macros::look_inside_iff(_dict_merge_loop_iff)]
fn _dict_merge_loop(
    w_dict: PyObjectRef,
    w_item: PyObjectRef,
    _unroll_safe: bool,
    w_function: PyObjectRef,
) -> Result<(), PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let root_base = _roots.pin_roots(&[w_dict, w_item, w_function]);
    let dict = || pyre_object::gc_roots::shadow_stack_get(root_base);
    let source = || pyre_object::gc_roots::shadow_stack_get(root_base + 1);
    let w_callable = || pyre_object::gc_roots::shadow_stack_get(root_base + 2);
    let keys_method = match crate::baseobjspace::getattr_str(source(), "keys") {
        Ok(m) => m,
        Err(e) if e.kind == crate::PyErrorKind::AttributeError => {
            return Err(crate::argument::type_error_oefmt(
                "Value after ** must be a mapping, not %T",
                &[crate::error::FmtArg::Obj(source())],
            ));
        }
        Err(e) => return Err(e),
    };
    let keys_method_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(keys_method);
    let keys_obj = crate::call::call_function_impl_result(
        pyre_object::gc_roots::shadow_stack_get(keys_method_slot),
        &[],
    )?;
    let keys_obj_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(keys_obj);
    let w_iterator = crate::type_methods::iter_mapping_keys(
        source(),
        pyre_object::gc_roots::shadow_stack_get(keys_obj_slot),
    )?;
    let iter_slot = pyre_object::gc_roots::shadow_stack_len();
    let _ = pyre_object::gc_roots::pin_root(w_iterator);
    loop {
        let w_key =
            match crate::baseobjspace::next(pyre_object::gc_roots::shadow_stack_get(iter_slot)) {
                Ok(k) => k,
                Err(e) => {
                    let (stop, e) = e.matches_stop_iteration_keep();
                    if stop {
                        break;
                    }
                    return Err(e);
                }
            };
        let _iteration_roots = pyre_object::gc_roots::push_roots();
        let key_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(w_key);
        let val = crate::baseobjspace::getitem(
            source(),
            pyre_object::gc_roots::shadow_stack_get(key_slot),
        )?;
        let val_slot = pyre_object::gc_roots::shadow_stack_len();
        let _ = pyre_object::gc_roots::pin_root(val);
        // `__contains__` runs Python, so the key is re-read from its slot
        // after it rather than held across it.
        let key = || pyre_object::gc_roots::shadow_stack_get(key_slot);
        if crate::baseobjspace::contains(dict(), key())? {
            return Err(crate::raise_type_error!(
                w_callable(),
                "got multiple values for keyword argument '%S'",
                &[crate::error::FmtArg::Obj(key())],
            ));
        }
        unsafe {
            pyre_object::w_dict_store(
                dict(),
                key(),
                pyre_object::gc_roots::shadow_stack_get(val_slot),
            )
        };
    }
    Ok(())
}

/// [3.14-spec] pyopcode.py _dict_merge_loop reads a dict source through keys() and space.getitem;
/// CPython v3.14.6 dict_merge takes the dict_dict_merge entry walk when
/// `PyDict_Check(b) && Py_TYPE(b)->tp_iter == dict_iter` (C source at tag v3.14.6, and measured:
/// `f(x=1, **D(a=1))` with D overriding __getitem__/keys and inheriting dict.__iter__ yields the
/// backing value and never calls keys()). Engineered as dictmultiobject.py rev_update1_dict_dict's
/// live storage walk plus _dict_merge_loop's contains_w check.
fn _dict_merge_dict(
    w_dict: PyObjectRef,
    w_item: PyObjectRef,
    w_function: PyObjectRef,
) -> Result<(), PyError> {
    let _roots = pyre_object::gc_roots::push_roots();
    let root_base = _roots.pin_roots(&[w_dict, w_item, w_function]);
    let dict = || pyre_object::gc_roots::shadow_stack_get(root_base);
    let source = || pyre_object::gc_roots::shadow_stack_get(root_base + 1);
    let w_callable = || pyre_object::gc_roots::shadow_stack_get(root_base + 2);
    let orig_size = unsafe {
        pyre_object::dictmultiobject::w_dict_len(
            crate::type_methods::resolve_dict_backing(source()),
        )
    };
    let mut i = 0;
    loop {
        let source_now = crate::type_methods::resolve_dict_backing(source());
        let Some(live) = (unsafe { pyre_object::dictmultiobject::w_dict_next_slot(source_now, i) })
        else {
            break;
        };
        i = live;
        let Some((k, v)) =
            (unsafe { pyre_object::dictmultiobject::w_dict_nth_item(source_now, i) })
        else {
            break;
        };
        let _iteration_roots = pyre_object::gc_roots::push_roots();
        let iteration_roots = pyre_object::gc_roots::pin_roots(&[k, v]);
        let key = || pyre_object::gc_roots::shadow_stack_get(iteration_roots);
        let value = || pyre_object::gc_roots::shadow_stack_get(iteration_roots + 1);
        if crate::baseobjspace::contains(dict(), key())? {
            return Err(crate::raise_type_error!(
                w_callable(),
                "got multiple values for keyword argument '%S'",
                &[crate::error::FmtArg::Obj(key())],
            ));
        }
        unsafe { pyre_object::w_dict_store(dict(), key(), value()) };
        if orig_size
            != unsafe {
                pyre_object::dictmultiobject::w_dict_len(crate::type_methods::resolve_dict_backing(
                    source(),
                ))
            }
        {
            return Err(PyError::runtime_error("dict mutated during update"));
        }
        i += 1;
    }
    Ok(())
}

